"use client";

import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { NarrifyLogo } from '@/assets/logo/NarrifyLogo';
import { Button } from '@/components/ui/button';
import { LucideIcon, LayoutDashboard, PlusCircle, Library, Settings, Bell, User, LogOut, Menu } from 'lucide-react';
import { cn } from '@/utils/cn';

const NAV_ITEMS = [
    { label: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
    { label: 'Create', href: '/create', icon: PlusCircle },
    { label: 'Voice Library', href: '/voices', icon: Library },
    { label: 'Settings', href: '/settings', icon: Settings },
];

export const MainLayout = ({ children }: { children: React.ReactNode }) => {
    const pathname = usePathname();
    const isAuthPage = pathname.startsWith('/auth');

    if (isAuthPage) return <>{children}</>;

    return (
        <div className="min-h-screen bg-narrify-background">
            {/* Navbar */}
            <header className="sticky top-0 z-50 glassmorphism border-b">
                <div className="container mx-auto px-4 h-16 flex items-center justify-between">
                    <Link href="/">
                        <NarrifyLogo />
                    </Link>

                    <nav className="hidden md:flex items-center gap-1">
                        {NAV_ITEMS.map((item) => (
                            <Link key={item.href} href={item.href}>
                                <Button
                                    variant="ghost"
                                    className={cn(
                                        "gap-2 px-4",
                                        pathname === item.href ? "text-narrify-blue bg-narrify-blue/5" : "text-slate-600"
                                    )}
                                >
                                    <item.icon size={18} />
                                    {item.label}
                                </Button>
                            </Link>
                        ))}
                    </nav>

                    <div className="flex items-center gap-3">
                        <Button variant="ghost" size="icon" className="text-slate-500">
                            <Bell size={20} />
                        </Button>
                        <div className="w-8 h-8 rounded-full bg-gradient-narrify p-[2px]">
                            <div className="w-full h-full rounded-full bg-white flex items-center justify-center text-xs font-bold text-narrify-blue">
                                JS
                            </div>
                        </div>
                    </div>
                </div>
            </header>

            <main className="container mx-auto px-4 py-8">
                {children}
            </main>

            <footer className="py-12 border-t mt-20 bg-white">
                <div className="container mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-8">
                    <NarrifyLogo className="opacity-50 grayscale" />
                    <p className="text-sm text-slate-400">© 2026 Narrify AI. Production Grade SaaS.</p>
                    <div className="flex gap-6 text-sm text-slate-500 font-medium">
                        <Link href="#" className="hover:text-narrify-blue">Privacy</Link>
                        <Link href="#" className="hover:text-narrify-blue">Terms</Link>
                        <Link href="#" className="hover:text-narrify-blue">Support</Link>
                    </div>
                </div>
            </footer>
        </div>
    );
};
